const query = $input.first().json.query || {};
const instId = String(query.instansi_id || query.instansi || 'bapperida').replace(/'/g, "''");

const DEFAULT = { enabled: false, toleransi: 30, times: [{ jam: '10:00', aktif: true }] };

const { rows } = await $pg.query("SELECT key, value FROM pengaturan WHERE key = 'kontrol_absen' AND instansi_id = $1", [instId]);
let config = DEFAULT;
if (rows.length) {
  try { config = { ...DEFAULT, ...JSON.parse(rows[0].value) }; } catch (_) {}
  if (!Array.isArray(config.times)) config.times = [];
}

return [{ json: { ok: true, config } }];

const input = $input.first().json;
const body = input.body || {};
const hdrs = input.headers || {};
const auth = String(hdrs.authorization || hdrs.Authorization || '').replace(/^Bearer\s+/i, '').trim();
const parts = auth.split('_');
const userId = parseInt(parts[1]);

if (!userId) {
  return [{ json: { ok: false, error: 'Unauthorized' } }];
}

const { rows } = await $pg.query('SELECT id, is_admin FROM user_list WHERE id = $1', [userId]);
if (!rows.length || !rows[0].is_admin) {
  return [{ json: { ok: false, error: 'Admin access required' } }];
}

const times = Array.isArray(body.times) ? body.times.map(t => ({
  jam: String(t.jam || '').slice(0, 5),
  aktif: t.aktif !== false
})) : [];
const value = JSON.stringify({
  enabled: !!body.enabled,
  toleransi: parseInt(body.toleransi, 10) || 30,
  times
});
const instId = String(body.instansi_id || 'bapperida').replace(/'/g, "''");

await $pg.query(
  "INSERT INTO pengaturan (id, key, value, instansi_id) " +
  "VALUES ((SELECT COALESCE(MAX(id), 0) + 1 FROM pengaturan), 'kontrol_absen', $1, $2) " +
  "ON CONFLICT (key, instansi_id) DO UPDATE SET value = EXCLUDED.value",
  [value, instId]
);

return [{ json: { ok: true, saved: value } }];
